<?php declare(strict_types=1);require_once __DIR__.'/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')exit;$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id)exit;$pdo=getPDO();$q=$pdo->prepare('SELECT imagen FROM alumnos WHERE id=?');$q->execute([$id]);$a=$q->fetch();if($a){$q=$pdo->prepare('DELETE FROM alumnos WHERE id=?');$q->execute([$id]);$file=realpath(__DIR__ . '/'.basename($a['imagen']));$base=realpath(__DIR__ . '/');if($file&&$base&&str_starts_with($file,$base.DIRECTORY_SEPARATOR)&&is_file($file))@unlink($file);}header('Location: index.php?msg='.urlencode('Alumno eliminado correctamente.'));exit;
